{
  "kind": "interface",
  "name": "@exact/in-app-browser",
  "version": "1.0.0",
  "substitute": "implementation",
  "shapes": {
    "InAppBrowserStatus": {
      "available": "bool",
      "overApp": "bool"
    },
    "BrowserResult": {
      "action": "enum<dismissed|opened>"
    }
  },
  "names": [
    {
      "source": "inAppBrowserStatus",
      "live": true,
      "overlays": "implementation",
      "answers": "InAppBrowserStatus",
      "sync": {
        "name": "inAppBrowserStatusSync",
        "from": "read"
      },
      "substitute": {
        "default": {
          "available": true,
          "overApp": false
        },
        "targets": {
          "ios": {
            "available": true,
            "overApp": true
          },
          "android": {
            "available": true,
            "overApp": true
          },
          "linux": {
            "available": false,
            "overApp": false
          },
          "tvos": {
            "available": false,
            "overApp": false
          }
        }
      }
    },
    {
      "send": "openBrowser",
      "request": true,
      "origin": "app",
      "foreground": true,
      "options": {
        "url": "string"
      },
      "answers": "BrowserResult",
      "substitute": {
        "choose": {
          "ticket": "browser",
          "choices": [
            "dismissed",
            "opened"
          ],
          "typed": false
        },
        "unsupported": [
          "linux",
          "tvos"
        ]
      }
    }
  ]
}
{
  "name": "@exact/in-app-browser",
  "version": "1.0.0",
  "private": true,
  "description": "A web page shown over the app with the platform's browser controls, or opened in the browser beside it (LLP 1133.024 Part II).",
  "exports": {
    ".": "./exact.json",
    "./apple": "./apple/exact.json",
    "./android": "./android/exact.json",
    "./web": "./web/exact.json"
  }
}
