      url = typeof reply.url === 'string' ? reply.url : '';
    } catch {
      url = '';
    }
  }
  if (url === '') url = (import.meta.env.SHOP_API_URL as string | undefined) ?? '';
  endpoint = url.trim() !== '' ? url.trim() : DEFAULT_ENDPOINT;
