async function gql(native: Native, operationName: string, query: string, variables: Record<string, unknown>): Promise<any> {
  const response = await fetch(apiUrl(native), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ operationName, query, variables }),
    exactTimeout: 30000,
  } as RequestInit);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const body = (await response.json()) as Gql;
  if (!body.data) throw new Error(body.errors?.[0]?.message ?? 'No data');
  return body.data;
}

