// ---- Home -----------------------------------------------------------------

async function loadHome(native: Native): Promise<Result<'loadHome'>> {
  const data = await gql(native, 'Home', HOME, {});
  return {
    loaded: true,
    collections: (data.collections?.nodes ?? []).map((c: any) => ({
      id: c.id,
      handle: c.handle,
      title: c.title,
      banner: sized(c.image?.url, 1080),
      image: sized(c.image?.url, 480),
