    if (paged.cursor) variables.after = paged.cursor;
    const data = await gql(native, 'Search', SEARCH, variables);
    const s = data.search;
    const offset = paged.cards.length;
    const nodes = (s?.nodes ?? []).filter((p: any) => p && p.id);
