let seq = 0;

function toCart(c: any): Cart {
  if (!c) return cart;
  return {
    id: c.id,
    checkoutUrl: c.checkoutUrl,
    totalQuantity: Number(c.totalQuantity ?? 0),
    subtotal: money(c.cost?.subtotalAmount),
