function updateLine(native: Native, lineId: string, quantity: number) {
  return cartCall(native, 'CartLinesUpdate', CART_LINES_UPDATE, { cartId: cart.id, lines: [{ id: lineId, quantity: Math.max(0, quantity) }] }, 'cartLinesUpdate');
}

