function homeReady(native: Native): Result<'homeReady'> {
  if (native?.available) {
    try {
      native.call({ op: 'ready' });
    } catch {
      // No module on this host.
    }
  }
  return { ok: true };
}

const sources: Sources = {
  loadHome: (_args, _store, _storage, native) => loadHome(native),
  loadCollection: ([handle, sort, pages], _store, _storage, native) => loadCollection(native, handle, sort, pages),
  searchProducts: ([query, pages], _store, _storage, native) => searchProducts(native, query, pages),
  loadProducts: ([handles], _store, _storage, native) => loadProducts(native, handles),
  addToCart: ([variantId], _store, _storage, native) => addToCart(native, variantId),
  updateLine: ([lineId, quantity], _store, _storage, native) => updateLine(native, lineId, quantity),
  homeReady: (_args, _store, _storage, native) => homeReady(native),
};

export const answer: Answer = (source, args, store, storage, native) =>
  sources[source](args, store, storage, native);

