   "type": "object",
   "additionalProperties": {
    "type": "string"
   }
  },
  "activate": {
   "type": "string",
   "enum": [
    "next-launch",
    "app-decides",
    "immediate"
   ]
  },
  "check": {
   "type": "object",
   "properties": {
    "interval": {
     "type": "number",
     "exclusiveMinimum": 0,
     "description": "Seconds between foreground update checks; defaults to 900 under every activation policy."
    },
    "background": {
     "type": "boolean"
    }
   },
   "additionalProperties": false
  },
  "sunset": {
   "type": "object",
   "additionalProperties": {
    "type": "object",
    "required": [
     "message"
    ],
    "properties": {
